      {
        "name": {
          "type": "string",
          "description": "第三位紧急联系人名称。",
          "sampleValue": "社区"
        },
        "phone": {
          "type": "string",
          "description": "第三位紧急联系人短电话号码展示。",
          "sampleValue": "119"
        }
      }
    ]
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/heart_fill.svg",
      "description": "心形实心图标，适合用于心率监测和健康状态提示。"
    },
    {
      "src": "resources/base/media/face.svg",
      "description": "简洁人脸轮廓图标，适合作为联系人头像。"
    }
  ]
}

